style.css:
@-moz-document domain("drive.google.com") {
body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;
        background: rgba(50, 0, 80, 0.85); /* dark purple tint */
        pointer-events: none; /* don’t block clicks */
        z-index: 999999; /* sit on top of everything */
    }

    /* Optional: make text lighter for readability */
    body, * {
        color: #f0e6ff !important;
    }
}
